// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzzed params: a nonzero-length array length and an arbitrary from address
    function testFuzz_property(uint256 len, address from) public {
        // keep length in a reasonable, still wide, range but allow zero to be filtered
        uint256 boundedLen = bound(len, 0, 10);
        vm.assume(boundedLen > 0); // admissible domain: non-empty arrays

        // deploy a helper that will accept the calls and always succeed
        RecorderAccepting callee = new RecorderAccepting();

        // build the _tos array of distinct recipient addresses (all point to the callee)
        address[] memory tos = new address[](boundedLen);
        for (uint i = 0; i < boundedLen; i++) {
            tos[i] = address(callee);
        }

        // Call transfer and observe whether it reverts or not via try/catch
        bool ok;
        try c.transfer(from, address(callee), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation always completes successfully (returns true) for any non-empty _tos
        // so ok must be true. The mutant that uses i <= _tos.length can access out-of-bounds and revert
        // for some inputs (e.g., any non-empty array) causing ok == false; thus this assertion distinguishes them.
        assertTrue(ok);
    }
}

// A minimal helper that accepts the call with the exact signature transferFrom(address,address,uint256)
// and always returns true. It also records how many times it was called so we observe c's outgoing behavior.
contract RecorderAccepting {
    uint256 public calls;
    address[] public froms;
    address[] public tos;
    uint256[] public vals;

    // match selector: transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        froms.push(from);
        tos.push(to);
        vals.push(v);
        return true; // always succeed
    }
}
